 const mine=record=>record&&record.ownerKey===owner;
 return {items:array(state.groupMoney?.items).filter(mine).map(groupRecord),invitations:array(state.groupMoney?.invitations).filter(mine).map(v=>safeRecord({...pick(v,['id','scenario','status','role','organiserName','title','targetCents','deadline','createdAt','expiresAt','collectionId','sample']),...(v.collection?{collection:groupRecord(v.collection)}:{})})),supportingFiles:'Metadata only; file contents are excluded.'};
