   data.preferences={...data.preferences,moneyUpdates:state.prefs?.payment!==false,spendingInsights:state.prefs?.insights!==false,push:state.prefs?.push===true,reviewSchedule:pick(state.dailyInsights?.prefs,['weekly','reviewDay','reviewTime','quiet','quietStart','quietEnd','privateUpdates'])};
   data.planning={saved:!!state.planSaved,expectedMoney:pick(state.allowance,['amount','date','source']),period:pick(state.planHorizon,['mode','date']),periodRecord:pick(state.budgetPeriodRecord,['start','costIds','createdAt','source'])};
   data.accountApplication=pick(state.setup,['applicationRef','applicationStatus','termsVersion','acceptedAt']);
