const runwayQuestion=q=>/\b(?:run(?:ning)? out|runway|burn rate|last until|last till|how long\b.*\b(?:money|balance|funds)|(?:money|balance|funds)\s+(?:(?:will|would|could|can|might)\s+)?(?:last|stretch)\b)/.test(q);
