/* Source: product-accounts.js | sha256:04603cc23b305625ebcf3fca990373485285fffa107af1e73cc639f0f3e0ae24 */
/* Customer-facing account split. Ledger, authorisation and migration live in
   two-account-engine; this module composes those same values on every surface. */
(()=>{
'use strict';
const E=L.e,M=L.money,B=L.btn;
const top=(title,back=true)=>`<div class="topline">${back?B(L.icon('arrowLeft',22),'L.back()','icon-btn').replace('<button ','<button aria-label="Go back" '):'<span class="wordmark wordmark-small"><img class="actual-wordmark lumo-wordmark-asset" src="/brand/Lumo-Wordmark-Black.svg" alt="Lumo"></span>'}<span class="eyebrow">${E(title)}</span>${B(L.icon('help',21),"L.go('help',{returnTo:L.route,returnParams:L.params})",'icon-btn').replace('<button ','<button aria-label="Get help" ')}</div>`;
const line=(label,value)=>`<div><dt>${E(label)}</dt><dd>${value}</dd></div>`;
const PM=(key,value,large=false)=>L.privateMoney(key,value,large);
const notice=()=>L.state.profile.campus&&!L.isLegonUniversity?.(L.state.profile.campus)?'<p class="notice pilot-campus-note">Built for Legon first. Some campus features may be limited here.</p>':'';
// Keep unsaved legacy goal metadata separate from the budget draft. No money
// is moved until the customer reviews and authorises a Money Box transfer.
const oldGoal=L.state.planDraft?.goalFields;
if(oldGoal?.name&&!L.state.moneyBoxDraft)L.state.moneyBoxDraft={name:oldGoal.name,target:oldGoal.target||'',date:oldGoal.date||''};
L.views.home=()=>{
 const s=L.state,b=L.balances(),a=L.accountBalances(),has=L.hasMeaningfulPlan(s),budget=L.budgetStateSummary?.(s);
 const name=E((s.profile.displayName||s.profile.name||'there').trim().split(/\s+/)[0]);
 const art=L.campusArt.draw(b.available?'home':'clarity','home');
 const boxes=(s.goals||[]).filter(box=>!box.archived&&!box.deleted).length;
 const primary=has?`<button class="account-room" onclick="L.go('${budget?.ended?'planPeriod':'planExplanation'}')" aria-label="${budget?.ended?'Budget period ended. Review dates':'Left after budget. See how it is calculated'}"><strong id="overview-room">${PM('room',b.room,true)}</strong><small class="home-balance-details">${budget?.ended?'Review budget dates':'See breakdown'} ${L.icon('chevron',14)}</small></button>`:`<div class="account-balance-primary"><strong id="overview-balance">${PM('available',a.available,true)}</strong></div>`;
 const supporting=has?`<div class="account-available account-available-secondary"><span>Available balance</span><strong id="overview-balance">${PM('available',a.available)}</strong></div>`:'';
 const privacy=L.balancePrivacyControl(true,has?'overview-room overview-balance overview-savings':'overview-balance overview-savings');
 const action=(label,icon,code,extra='')=>B(L.icon(icon,19)+'<span>'+label+'</span>',code,extra);
 return `<section class="accounts-home home-refined home-minimal home-restored edition-home" data-illustrated-screen="home"><h1 class="sr-only">Home</h1><div class="home-greeting"><span class="wordmark" aria-label="Lumo"><img class="actual-wordmark lumo-wordmark-asset" src="/brand/Lumo-Wordmark-Black.svg" alt="Lumo"></span><div class="inline home-header-actions">${B(L.icon('bell',22),"L.go('notifications')",'icon-btn').replace('<button ','<button aria-label="Updates" ')}${B(name[0],"L.go('profile')",'avatar').replace('<button ','<button aria-label="Your profile" ')}</div></div>${notice()}<div class="accounts-welcome"><p>Hey, ${name}.</p></div><section class="account-card account-operational${has?' has-budget':''}${Math.abs(has?b.room:a.available)>=10000?' has-wide-amount':''}" aria-label="${has?'Left after budget':'Available balance'}"><div class="home-card-heading"><span>${has?'Left after budget':'Available balance'}</span>${privacy}</div><div class="account-intelligence">${primary}<div class="accounts-home-art">${art}</div></div>${supporting}${a.held?`<button class="home-pending-status" onclick="L.go('pending')">Payment in progress ${L.icon('chevron',14)}</button>`:''}</section>${has&&b.gap?`<button type="button" class="text-btn edition-budget-gap" onclick="L.go('makeRoom')">Your Budget needs attention. ${L.icon('chevron',14)}</button>`:''}<div class="home-funding-actions focus-main-actions" aria-label="Quick actions">${action('Add money','plus',"L.openFunding('home')",'primary home-add-money')}${action('Request money','arrowDown','L.newRequest()','secondary')}</div><div class="home-payment-actions" aria-label="Make a payment">${action('Campus Pay','scan',"L.go('campusPay')",'secondary home-campus-pay')}${action('Transfers','arrowUp',"L.go('sendOptions')",'secondary home-transfers')}</div><section class="account-card account-savings restored-savings" aria-label="Money Boxes"><button type="button" class="restored-savings-line" onclick="L.go('goals')" aria-label="Money Boxes. See your saved money"><span class="restored-savings-icon" aria-hidden="true">${L.icon('target',21)}</span><span class="restored-savings-copy"><strong>Money Boxes</strong><small>${boxes?'Saved separately':'Save for what matters'}</small></span><strong id="overview-savings">${PM('savings',a.savings)}</strong>${L.icon('chevron',16)}</button></section>${Number(s.accounts?.migration?.unfunded)>0?`<p class="notice">${M(s.accounts.migration.unfunded)} of an old goal allocation could not be moved into savings. ${B('Review boxes',"L.go('goals')",'text-btn')}</p>`:''}</section>`;
};
L.views.plan=()=>{
 const b=L.balances(),s=L.state,has=L.hasMeaningfulPlan(s),start=s.planDraft?.step||'planSetup';
 return `<section class="account-budget-page" data-illustrated-screen="plan">${top('Budget',false)}<div class="destination-heading"><h1>${has?'Your everyday costs.':'Give your money a job.'}</h1><p>${has?'Paid from your operational account.':'Save the costs this money needs to cover.'}</p></div><div class="account-budget-art">${L.campusArt.draw('plan','plan',true)}</div>${has?`<div class="budget-summary"><span>Left after budget</span><strong>${L.balanceNumber(b.room)}</strong><p>${M(b.available)} available − ${M(b.essentials)} budget remaining</p>${b.gap?`<p class="warning">${M(b.gap)} of your budget is uncovered.</p>`:''}</div><div class="actions">${B('Edit budget',"L.go('planEdit')")}${B('Add a budget item',"L.go('essentialEdit')",'secondary')}</div><div class="destination-list">${L.row('Budget period',L.planPeriodActionLabel?.()||'How long should this money last? Add a date.','plan',"L.go('planPeriod')")}${L.row('How this is calculated','Uses only your saved costs','help',"L.go('planExplanation')")}</div>`:`<div class="actions">${B(s.planDraft?'Continue budget':'Add a budget',`L.go('${E(start)}')`)}${B('How a budget helps',"L.openPlanBenefit()",'text-btn')}</div>`}<div class="budget-savings-link">${L.row('Money Boxes','A separate place to save in your savings account','target',"L.go('goals')")}</div></section>`;
};
L.views.balances=()=>{
 const b=L.balances(),a=L.accountBalances();
 return `<section class="account-breakdown">${top('Your accounts')}<div class="page-heading"><h1>Two accounts. Clear roles.</h1></div><h2>Operational</h2><dl class="balance-calculation">${line('Confirmed balance',M(a.operational))}${line('Held for pending payments',M(a.held))}${line('Available to use',M(a.available))}${line('Budget still to cover',M(b.essentials))}${line('Left after budget',M(b.room))}</dl><h2>Savings</h2><dl class="balance-calculation">${line('Money Boxes total',M(a.savings))}${a.savingsHeld?line('Held for a transfer back',M(a.savingsHeld)):''}</dl><p>Money Boxes are already in savings. They are not deducted from your operational balance again. Move money back before spending it. Protected boxes also need partner approval.</p><div class="actions">${B('View Money Boxes',"L.go('goals')")}${B('Done','L.taskSheet?.active?L.closeTask():L.back()','secondary')}</div></section>`;
};
L.views.accountInfo=()=>{
 if(!L.state.onboarded||L.state.locked)return L.views.signin();
 const a=L.accountBalances(),p=L.state.profile;
 if(L.state.closed)return `<section class="account-details-page">${top('Saved account records')}<div class="page-heading"><h1>Account closed.</h1></div><p class="notice">These are read-only records from this browser. No money can be added, sent or moved into Money Boxes.</p><h2>${E(p.name)}</h2><div class="receipt">${line('Status','Closed in this preview')}${L.state.closure?.date?line('Closure confirmed',E(L.state.closure.date)):''}</div><div class="list">${L.row('Statements','Download retained activity','download',"L.go('statements')")}${L.row('Download your data','Keep a copy of your saved records','download',"L.go('dataExport')")}${L.row('Help & support','Saved reports and account questions','help',"L.go('help')")}</div>${B('Sign out','L.acct.signout()','secondary')}<p class="small muted">This is a sample account. Closure did not contact a live provider.</p></section>`;
 return `<section class="account-details-page">${top('Your accounts')}<div class="page-heading"><h1>Your Lumo accounts.</h1></div><p class="notice">Sample account details. Do not send real money.</p><h2>${E(p.name)}</h2><p class="small muted">Receiving bank · GCB Bank</p>${[['Operational account',a.operationalNumber,a.available],['Savings account',a.savingsNumber,a.savings]].map(([label,number,value])=>`<div class="account-detail-card"><h3>Lumo ${label.toLowerCase()}</h3><dl>${line('Account number',E(number))}${line(label==='Savings account'?'Money Boxes total':'Available balance',M(value))}</dl>${B('Copy '+label.toLowerCase()+' number',`L.copy('${String(number).replace(/\D/g,'')}')`,'secondary')}</div>`).join('')}<div class="list">${L.row('Add money','Mobile money or bank transfer via GIP','plus',"L.openFunding('accountInfo')")}${L.row('Money Boxes','Create, fund or transfer back','target',"L.go('goals')")}${L.row('Statements','Download your activity','download',"L.go('statements')")}${L.row('Fees, limits & terms','Know the details before you pay','receipt',"L.go('accountTerms')")}${L.row('Close accounts','Review balances and unfinished activity','close',"L.go('closeAccount')")}</div></section>`;
};
const blockers=L.acct.blockers;L.acct.blockers=()=>{
 const items=blockers(),a=L.accountBalances();
 if(a.savings>0)items.push({label:'Money in your savings account',sub:M(a.savings)+' in Money Boxes. Transfer it back before closing.',route:'goals'});
 return items;
};
// Use the same ledger rows but identify internal movements without a misleading
// income/spending sign. Filters for incoming/outgoing still exclude them.
for(const route of ['activity','pending']){
 const view=L.views[route];L.views[route]=()=>{
  let html=view();
  for(const t of L.state.txs.filter(L.isInternalTransfer)){
   const marker=`L.go('txDetail',{id:'${t.id}'})`,amount=(t.type==='in'?'+':'−')+M(Number(t.amount)+Number(t.fee||0));
   const start=html.indexOf(marker);if(start<0)continue;
   const end=html.indexOf('</button>',start);if(end<0)continue;
   const row=html.slice(start,end),replacement=row.replace(amount,'↔ '+M(t.amount));
   html=html.slice(0,start)+replacement+html.slice(end);
  }
  return html;
 };
}
const downloadData=L.acct.downloadData;L.acct.downloadData=()=>{
 if(!L.state.accounts)return downloadData();
 // Existing export keeps its PIN check; add accounts through the one download
 // callback instead of weakening authentication or duplicating its checks.
 const download=L.download;L.download=function(name,content,type){
  if(name==='Lumo-Demo-Data.json'){const data=JSON.parse(content);data.accounts=L.state.accounts;data.budget=data.plan.essentials;data.moneyBoxes=data.plan.goals;delete data.plan;content=JSON.stringify(L.acct.sanitizeExport?L.acct.sanitizeExport(data):data,null,2);}
  return download.call(this,name,content,type);
 };try{return downloadData();}finally{L.download=download;}
};
})();

;
/* Source: funding-budget.js | sha256:97f98d51a79c283fb390f7b15c20ad890230241b7381941eaede5e32a0591e2a */
/* Confirmed money arrives in the operational account before optional budgeting.
   The bank guide and every credit in this preview are explicitly simulated. */
(()=>{
'use strict';
const E=L.e,M=L.money,B=L.btn;
const transaction=id=>(L.state.txs||[]).find(t=>t.id===id);
const hasBudget=()=>(L.state.essentials||[]).some(cost=>Number(cost.amount)>0);
const account=()=>{
 L.ensureAccounts?.();
 return {name:L.state.profile.name,number:L.accountBalances?.().operationalNumber||L.state.profile.account};
};
const currentFunding=()=>transaction(L.route==='bankAdd'?L.state.bankFunding?.txId:L.route==='momoAdd'?L.state.fundingDraft?.txId:null);
const confirmed=t=>t?.type==='in'&&t.status==='success'&&!t.internal&&!L.isInternalTransfer?.(t);
const paymentReturn=()=>L.state.fundingReturn==='paymentReview';
const eligible=t=>confirmed(t)&&!paymentReturn()&&!t.budgetPromptHandled&&!(L.state.budgetPrompt?.txId===t.id&&L.state.budgetPrompt.done);
const nextLabel=t=>eligible(t)?hasBudget()?'Review budget':'Set up budget':paymentReturn()?'Return to payment':'Done';
const row=(label,value)=>`<div class="summary-line"><span>${E(label)}</span><strong>${E(value)}</strong></div>`;
const error='<div id="error" role="alert" aria-live="polite"></div>';

L.beginFirstFunding=()=>{
 if(!L.state.onboarded)return L.go('welcome');
 L.ensureAccounts?.();
 L.state.onboardingFunding={startedAt:new Date().toISOString(),done:false};
 L.state.fundingReturn='home';
 L.save();L.go('addMoney');
};
const closePrompt=()=>{
 const prompt=L.state.budgetPrompt;
 if(prompt){prompt.done=true;const t=transaction(prompt.txId);if(t)t.budgetPromptHandled=true;}
 if(L.state.onboardingFunding)L.state.onboardingFunding.done=true;
 L.state.fundingReturn=null;L.save();
};
const offerBudget=t=>{
 if(!eligible(t))return false;
 L.state.budgetPrompt={txId:t.id,done:false,hasBudget:hasBudget()};
 if(L.state.onboardingFunding)L.state.onboardingFunding.done=true;
 L.state.fundingReturn=null;L.save();L.go('budgetAfterFunding');return true;
};
const firstFundingResult=()=>{
 const t=currentFunding();
 // Only confirmed credit can advance the first-funding journey. A wallet
 // approval, a bank debit or a status check is never evidence of incoming money.
 if(L.state.onboardingFunding&&!L.state.onboardingFunding.done&&eligible(t))offerBudget(t);
};
const done=L.fundingDone;
L.fundingDone=function(){if(offerBudget(currentFunding()))return;return done?.apply(this,arguments);};
for(const key of ['requestMomoFunding','fundingOutcome']){
 const action=L[key];
 L[key]=function(...args){const run=()=>{const result=action?.apply(this,args);firstFundingResult();return result;};try{return L.persistence?.transaction?L.persistence.transaction(run,{financial:true,label:'Confirm incoming sample money'}):run();}catch(error){L.render();L.error(error.message||'The incoming money could not be saved. Keep the same reference.');return false;}};
}
const momoView=L.views.momoAdd;
L.views.momoAdd=()=>{
 const html=momoView(),t=transaction(L.state.fundingDraft?.txId);
 if(!confirmed(t))return html;
 return html.replace(/(<button\b[^>]*onclick="L\.fundingDone\(\)"[^>]*>)[\s\S]*?(<\/button>)/,(_,open,close)=>open+E(nextLabel(t))+close);
};
L.views.budgetAfterFunding=()=>{
 const prompt=L.state.budgetPrompt,t=transaction(prompt?.txId);
 if(!confirmed(t))return `<section>${L.header('Add money first','Your balance updates only after money arrives.')}<div class="actions">${B('Add money',"L.go('addMoney')")}${B('Back to Home',"L.openTab('home')",'text-btn')}</div></section>`;
 const existing=hasBudget();
 return `<section class="funding-budget-prompt" data-illustrated-screen="budgetAfterFunding">
 ${L.header(existing?'Money added. Review your budget?':'Money added. Give it a budget.')}
 <div class="notice"><span class="avatar" aria-hidden="true">${L.icon('check',26)}</span><strong>${M(t.amount)} added to your operational account.</strong><p class="small">Confirmed sample money · no live transfer.</p></div>
 <p>${existing?'Your saved budget stays in place. Check whether it still covers what you need.':'A budget tells Lumo what this money needs to cover, like food, transport and data.'}</p>
 <p class="small muted">${existing?'Adding money doesn’t restart your budget or change your costs.':'Then Lumo shows what’s left and helps you see what a payment would change. Creating a budget doesn’t move or lock your money.'}</p>
 <div class="actions">${B(existing?'Review budget':L.state.planDraft?'Continue budget':'Build my budget','L.beginFundedBudget()')}${B('Do later','L.deferFundedBudget()','secondary')}</div>
 </section>`;
};
L.beginFundedBudget=()=>{
 const t=transaction(L.state.budgetPrompt?.txId);if(!confirmed(t))return;
 const existing=hasBudget();closePrompt();
 if(existing)return L.go('planEdit');
 if(L.buildPlanFromBenefit)return L.buildPlanFromBenefit();
 return L.go('firstEssentials');
};
L.deferFundedBudget=()=>{closePrompt();L.openTab('home');};
const beforeNavigate=L.beforeNavigate;
L.beforeNavigate=function(route,...args){
 if(L.route==='budgetAfterFunding'&&route!=='budgetAfterFunding')closePrompt();
 return beforeNavigate?.call(this,route,...args);
};

L.startBankFunding=()=>{
 L.ensureAccounts?.();
 const previous=L.state.bankFunding,t=transaction(previous?.txId);
 // Reopening an unfinished instruction sheet preserves its sample amount.
 // A completed transfer starts a new draft; its reference can never be reused.
 if(!previous||t&&t.status!=='pending')L.state.bankFunding={id:L.id('BF'),...(t?.status==='failed'?{amount:previous.amount??t.amount}:{})};
 L.save();L.go('bankAdd');
};
L.bankDetailsText=()=>{const a=account();return 'Sample Lumo receiving details. Do not send real money.\nBank: GCB Bank (sample)\nAccount name: '+a.name+'\nOperational account number: '+a.number;};
L.copyBankDetails=()=>L.copy(L.bankDetailsText());
L.copyOperationalNumber=()=>L.copy(String(account().number));
L.bankSent=()=>L.toast('An outgoing bank transfer is not confirmed Lumo credit. Wait until it appears in your incoming activity.');
L.simulateBankReceipt=()=>{
 if(!L.state.onboarded||L.state.locked||L.state.closed)return L.go('signin');
 const f=L.state.bankFunding||(L.state.bankFunding={id:L.id('BF')});
 if(f.txId){L.go('bankAdd');firstFundingResult();return;}
 const raw=L.value('bank-test-amount'),amount=Number(raw);
 f.amount=raw;L.save();
 if(!raw||!Number.isFinite(amount)||amount<0.01||amount>5000||Math.abs(amount*100-Math.round(amount*100))>0.000001)return L.error('Enter GH₵0.01 to GH₵5,000.00, using no more than 2 decimal places.','bank-test-amount');
 const a=account();
 const t=L.addTx({draftId:f.id,type:'in',name:'Bank transfer received',amount:Math.round(amount*100)/100,fee:0,status:'success',category:'Top ups',method:'GIP incoming',destination:a.number,note:'Simulated confirmed incoming bank credit. No bank transfer was made.'});
 f.txId=t.id;L.save();L.go('bankAdd');firstFundingResult();
};
// Retain the tester entry point while exposing the same explicit simulation
// to ordinary prototype visitors. Both use one idempotent ledger operation.
const simulateBankReceipt=L.simulateBankReceipt;
L.simulateBankReceipt=function(...args){try{return L.persistence?.transaction?L.persistence.transaction(()=>simulateBankReceipt.apply(this,args),{financial:true,label:'Confirm incoming bank money'}):simulateBankReceipt.apply(this,args);}catch(error){L.render();L.error(error.message||'The incoming transfer could not be saved. Keep the same reference.');return false;}};
L.testBankCredit=L.simulateBankReceipt;
document.addEventListener('input',event=>{
 if(L.route!=='bankAdd'||event.target?.id!=='bank-test-amount'||document.getElementById('bank-test-amount')!==event.target||L.state.bankFunding?.txId)return;
 L.state.bankFunding.amount=String(event.target.value||'');L.save();
});
L.views.bankAdd=()=>{
 const a=account(),f=L.state.bankFunding||(L.state.bankFunding={id:L.id('BF')}),t=transaction(f.txId);
 if(t){
  const success=confirmed(t),pending=t.status==='pending';
  const receiptAction=pending?`L.refreshPayment('${E(t.id)}')`:`L.go('txDetail',{id:'${E(t.id)}'})`;
  return `<section class="bank-funding-result">${L.header(success?'Money added.':pending?'Waiting for the transfer.':'Transfer not completed.')}
  <div class="notice"><span class="avatar" aria-hidden="true">${L.icon(success?'check':pending?'clock':'close',26)}</span><strong>${M(t.amount)}${success?' received':pending?' not received yet':' was not added'}.</strong><p class="small">${success?'Confirmed sample money.':pending?'Your balance changes only when incoming money is confirmed.':'Your balance has not been credited.'}</p></div>
  <div class="receipt">${row('Account','Operational · '+a.number)}${row('Reference',t.id)}${row('Status',success?'Completed':pending?'Pending':'Not completed')}</div>
  <div class="actions">${B(nextLabel(t),'L.fundingDone()')}${B(pending?'Check status':'View receipt',receiptAction,'secondary')}${!success&&!pending?B('Try another sample transfer','L.startBankFunding()','text-btn'):''}</div><p class="preview-boundary">Sample money. No live bank transfer.</p></section>`;
 }
 return `<section class="bank-funding-guide" data-illustrated-screen="bankAdd">${L.header('Add from your bank','Use GIP in your existing bank app.')}
 <p class="preview-boundary"><strong>Sample account. Do not send real money.</strong></p>
 <div class="receipt">${row('Receiving bank','GCB Bank (sample)')}${row('Account name',a.name)}${row('Operational account',a.number)}</div>
 <div class="grid2">${B('Copy account number','L.copyOperationalNumber()','secondary')}${B('Copy all details','L.copyBankDetails()','secondary')}</div>
 <details class="optional-fields" open><summary>How to send with GIP</summary><ol class="small"><li>Open your bank app and choose <strong>Transfers</strong>.</li><li>Select <strong>Other bank</strong>, <strong>GIP</strong> or <strong>InstantPay</strong>.</li><li>Choose <strong>GCB Bank</strong> and enter your Lumo operational account number.</li><li>Check the beneficiary name and enter the amount.</li><li>Authorise the transfer in your bank app.</li><li>Wait for the incoming transfer to be confirmed in Lumo.</li></ol><p class="tiny muted">Labels vary between bank apps. A bank debit or “I sent it” does not confirm receipt.</p></details>
 <details class="optional-fields"${L.state.onboardingFunding&&!L.state.onboardingFunding.done?' open':''}><summary>Try a sample bank transfer</summary><p class="small muted">For this prototype only. This adds sample money without contacting a bank.</p><form class="form" onsubmit="event.preventDefault();L.simulateBankReceipt()"><label class="field" for="bank-test-amount"><span>Sample amount</span><div class="inline payment-amount-row"><span class="payment-currency" aria-hidden="true">GH₵</span><input id="bank-test-amount" class="input amount-input" type="number" inputmode="decimal" min="0.01" max="5000" step="0.01" required aria-label="Sample amount in Ghana cedis" aria-describedby="error" value="${E(f.amount??'')}" placeholder="0.00"></div></label>${error}<button type="submit" class="primary">Simulate received money</button></form></details>
 <div class="actions">${B('Check incoming activity',"L.go('activity',{filter:'in'})",'text-btn')}${B(paymentReturn()?'Return to payment':'Done','L.fundingDone()','secondary')}</div>
 </section>`;
};
})();

;
/* Source: plan-hub.js | sha256:b53ead35cb0b241bee0d79306489d116c7ceaa7c1726c129d846506f190903b6 */
/* One Plan destination, two distinct jobs. Budget checks operational money;
   Money Boxes hold savings. Navigation and financial authority stay unchanged. */
(()=>{
'use strict';
const E=L.e,M=L.money,B=L.btn;
const top=()=>`<div class="topline plan-hub-top"><span class="wordmark wordmark-small"><img class="actual-wordmark lumo-wordmark-asset" src="/brand/Lumo-Wordmark-Black.svg" alt="Lumo"></span><span class="eyebrow">Plan</span>${B(L.icon('help',21),"L.go('help',{returnTo:'plan'})",'icon-btn').replace('<button ','<button aria-label="Get help" ')}</div>`;
const setupSteps=new Set(['planSetup','firstEssentials','firstPlanReview']);
L.views.plan=()=>{
 const s=L.state,b=L.balances(),a=L.accountBalances(),has=L.hasMeaningfulPlan(s);
 const boxes=s.goals.filter(box=>!box.archived),count=boxes.length;
 const start=setupSteps.has(s.planDraft?.step)?s.planDraft.step:'planSetup';
 const budgetActions=has
  ?`${B('Edit budget',"L.go('planEdit')")}${B('Add a budget item',"L.go('essentialEdit')",'secondary')}`
  :`${B(s.planDraft?'Continue budget':'Create a budget',`L.go('${E(start)}')`)}`;
 const budgetSummary=has
  ?`<div class="budget-summary plan-hub-summary"><span>Left after budget</span><strong class="plan-hub-amount">${L.balanceNumber(b.room)}</strong><p class="plan-hub-facts">${M(b.essentials)} of everyday costs still to cover.</p>${b.gap?`<p class="plan-hub-shortfall">${L.icon('help',16)} ${M(b.gap)} of your budget is uncovered.</p>`:''}</div>`
  :`<p class="plan-hub-empty">Cover food, transport and other costs.</p>`;
 return `<section class="plan-hub account-budget-page" data-illustrated-screen="plan">
 ${top()}<div class="plan-hub-heading"><h1>Your plan.</h1></div>
 <section class="plan-budget-section" aria-labelledby="plan-budget-title">
 <div class="plan-section-heading"><span class="plan-section-icon" aria-hidden="true">${L.icon('plan',22)}</span><div><h2 id="plan-budget-title">Budget</h2><span>Operational account</span></div></div>
 ${budgetSummary}<div class="plan-hub-actions">${budgetActions}</div>
 <details class="plan-hub-details"><summary>${has?'Budget details':'Budget tools'} ${L.icon('chevron',16)}</summary><div class="plan-hub-detail-actions">${has?`${L.row('Budget period',L.planPeriodActionLabel(),'plan',"L.go('planPeriod')")}${L.row('See the calculation','Uses only your saved budget costs','help',"L.go('planExplanation')")}${L.row('Expected money','Excluded until it arrives','arrowDown',"L.go('allowance')")}`:B('How it works',"L.openPlanBenefit()",'text-btn')}</div></details>
 </section>
 <section class="plan-boxes-section budget-savings-link" aria-labelledby="plan-boxes-title">
 <div class="plan-section-heading"><span class="plan-section-icon" aria-hidden="true">${L.icon('target',22)}</span><div><h2 id="plan-boxes-title">Money Boxes</h2><span>Savings account</span></div></div>
 <div class="plan-hub-summary plan-boxes-summary"><strong class="plan-hub-amount">${L.balanceNumber(a.savings)}</strong><p class="plan-hub-facts">${count?`${count} Money Box${count===1?'':'es'}${a.savingsHeld?' · transfer in progress':''}`:'A laptop, a trip or a little backup.'}</p></div>
 <div class="plan-hub-actions">${count?B('View Money Boxes',"L.go('goals')",'secondary'):''}${B(count?'Add a box':'Create a Money Box',"L.go('goalEdit')",'secondary')}</div>

 </section></section>`;
};
})();

