  const params=i.route==='dailyMoneyStory'?`,{period:'${i.period}'}`:'',action=i.kind==='period'?renewAction():i.kind==='due'?`L.openDueBudgetCost(${E(JSON.stringify(i.costId))})`:`L.go('${i.route}'${params})`;
