const recent=()=>{
 const seen=new Set();
 return [...(L.state.txs||[])].sort((a,b)=>new Date(b.date)-new Date(a.date)).filter(t=>{if(!canRepeat(t))return false;const key=currentDescriptor(t).key;if(seen.has(key))return false;seen.add(key);return true;}).slice(0,5);
};
