L.chatSnapshotStatusExtra=function(reply){return snapshotExtra?.apply(this,arguments)||(reply?.context?.moneyLifeMark&&reply.context.moneyLifeMark!==iouMark()?'Your IOU records changed. Ask again for current amounts.':'');};
